@extends('layouts.app') @section('title','Tracking Surat') @section('content')<div class="container py-4"><h2 class="fw-bold">{{ $letterRequest->request_number }}</h2><p>{{ $letterRequest->letterType->title }} — {{ $letterRequest->subject }}</p><div class="card border-0 shadow-sm mb-4"><div class="card-body"><h5>Alur Surat</h5><div class="row g-2">@foreach($letterRequest->letterType->workflowSteps as $s)@php $done=$letterRequest->histories->where('step_order',$s->step_order)->where('action','approve')->isNotEmpty(); $active=$letterRequest->status==='in_process'&&$letterRequest->current_step_order==$s->step_order; @endphp<div class="col-md"><div class="p-3 rounded {{ $done?'bg-success-subtle':($active?'bg-warning-subtle':'bg-light') }}"><div class="small">Tahap {{ $s->step_order }}</div><strong>{{ $done?'✓ ':($active?'● ':'○ ') }}{{ $s->label }}</strong><div class="small text-secondary">{{ str_replace('_',' ',$s->role) }}</div></div></div>@endforeach</div></div></div><div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><h5>Riwayat Surat</h5>@foreach($letterRequest->histories as $h)<div class="border-start border-3 ps-3 mb-3"><strong>{{ $h->action }}</strong> @if($h->step_order)• tahap {{ $h->step_order }}@endif<br><span>{{ $h->notes }}</span><br><small class="text-secondary">{{ $h->actor?->name ?? 'Sistem' }} • {{ $h->created_at->format('d M Y H:i') }}</small></div>@endforeach</div></div></div><div class="col-lg-5"><div class="card border-0 shadow-sm mb-3"><div class="card-body"><h5>Lampiran</h5>@forelse($letterRequest->files as $f)<a class="d-block" target="_blank" href="{{ asset('storage/'.$f->file_path) }}">{{ $f->requirement->title }}</a>@empty<span class="text-secondary">Tidak ada lampiran.</span>@endforelse</div></div>@if($letterRequest->status==='in_process' && $current && $current->role===auth()->user()->role)<div class="card border-primary shadow-sm"><div class="card-body"><h5>Proses Tahap Anda</h5><p class="